onb, 3),
  ('ambergris-caye-belize', '10S', 'Ambergris Caye / San Pedro', 'Belize', 'Ambergris Caye Belize', 'live', 'verified', 'tropicalBeach', 'Belize', '{"tropical","liveaboard","romance","expedition"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Belize''s largest island and #1 tourism engine; runs parallel to the UNESCO Belize Barrier Reef, ~35 mi NE of Belize City.","Hol Chan Marine Reserve (est. 1987, ~4 mi south of San Pedro) protects ~18 km2 with 160+ fish species; Shark Ray Alley added 1999.","Belize''s national recompression capability is on-island: SSS hyperbaric chamber (since 1989) + DAN-affiliated Belize Chamber Project (2015), both 24/7.","Air access via BZE Philip Goldson Intl -> SPR San Pedro, ~20-min puddle-jumper (Tropic Air / Maya Island Air) or ~90-min water taxi via Caye Caulker.","English is Belize''s official language - the only English-official nation in Central America."],"safety":{"emergency":"911 (also 90); San Pedro Police 206-2022; San Pedro Coast Guard 222-5260","hyperbaric_chamber":"YES - on Ambergris/San Pedro: SSS Belize Hyperbaric Facility (est. 1989, 4-diver lock, US Navy tables, 24/7) + DAN-affiliated Belize Chamber Project (2015). National dive-safety asset.","hospital":"Lighthouse Medical Center (San Pedro, private) for urgent care; serious trauma -> Karl Heusner Memorial Hospital (KHMH), Belize City - the only trauma centre in Belize; then US evac. Island remoteness flagged.","l3_disclosure":true,"stay_in_zone":true,"air_access_verified":true,"malaria":"none on the cayes; Belize WHO-certified malaria-free 2023; small mainland Cayo District cluster (Apr 2025) - mainland only","water":"do not drink tap water on the cayes; use bottled/filtered","mosquito_borne":"dengue primary concern; also chikungunya, Zika (day-biting Aedes) - use repellent","founder_policy_note":"only Southside Belize City is the named danger","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/belize","read":"2026-09-01T16:20:07Z","page_updated":"2026-06-12T10:40:30+01:00","source_country":"belize","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"inflection_curve_start":"2026-12-20","peak":"late-Dec through April (dry season); dive peak extends to June","fire_date":"2026-12-08","fire_date_secondary":"2026-11-01 (Mar-Apr dive/whale-shark surge, 4-6 mo lead)","shoulder":"September-November (wet/green season, lower rates)","green":"September-November","booking_lead":"4-6 months (dive/liveaboard/atoll + ultra private-island)","off_season_specials":"green-season weekly/monthly villa & condo discounts","event_peaks":["San Pedro Lobster Festival (early summer; 2026 advertised Jul 1-12)","Costa Maya Festival (August; 2026 dates unverified)"],"whale_shark_window":"Mar-Jun full-moon (2026 full moons Mar 14, Apr 13); Apr-May best"},"jewels":[{"name":"Hol Chan Marine Reserve (Zone A)","status":"live","hook":"Signature 30-ft dive/snorkel; moray, turtles, 160+ fish species in a protected channel.","bookable_category":"guided dive/snorkel","tier":"comfort","source":"https://en.wikipedia.org/wiki/Hol_Chan_Marine_Reserve + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Signature 30-ft dive/snorkel; moray, turtles, 160+ fish species in a protected channel.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","liveaboard"],"shelf_fit":{"diveglobal":"evidenced","expedition":"destination","liveaboard":"primary","romance":"destination","tropical":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Dive Liveaboards / Reef Diving","si_map_basis":"normalised from free text ''Dive Live