ssion":"David CLIA dive lane","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","expedition","liveaboard","tropical"],"shelf_fit":{"diveglobal":"evidenced","expedition":"evidenced","liveaboard":"primary","romance":"destination","tropical":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Dive Liveaboards / Reef Diving","si_map_basis":"normalised from free text ''Dive Liveaboards / Reef Diving'' by gen_normalise_jewel_si"},{"name":"Grand Slam fly-fishing (bonefish + permit + tarpon)","status":"live","hook":"400+ sq mi of flats; El Pescador Orvis-endorsed base; all three species in a day.","bookable_category":"lodge / guided angling","tier":"luxury","source":"https://www.elpescador.com/articles/from-bonefish-to-tarpon-the-anglers-guide-to-el-pescadors-grand-slam/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"400+ sq mi of flats; El Pescador Orvis-endorsed base; all three species in a day.","when":"late-Dec through April","commission":"CLIA + Fora (lodge/villa)","accessed":"2026-07-06","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","liveaboard":"destination","romance":"destination","tropical":"destination"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Gladden Spit whale-shark encounter","status":"live","hook":"Mar-Jun full-moon aggregation; snorkel/dive with whale sharks (mainland-launched marquee day-add).","bookable_category":"guided dive/snorkel","tier":"premier","source":"https://belizescuba.com/diving-snorkeling/whale-sharks/ + Accessed 2026-07-06","si":"expedition","blurb":"Mar-Jun full-moon aggregation; snorkel/dive with whale sharks (mainland-launched marquee day-add).","commission":"David CLIA dive lane","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","liveaboard":"destination","romance":"destination","tropical":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Caye Caulker day trip","status":"live","hook":"Car-free ''go slow'' sister island 30 min by boat; the Split, cheaper eats.","bookable_category":"day tour / water taxi","tier":"essential","source":"https://www.viaventure.com/destinations/belize/ambergris-caye/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Car-free ''go slow'' sister island 30 min by boat; the Split, cheaper eats.","when":"late-Dec through April","commission":"tour affiliate (Viator) + water taxi","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","tropical"],"shelf_fit":{"expedition":"primary","liveaboard":"destination","romance":"destination","tropical":"evidenced"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Secret Beach (west side)","status":"live","hook":"Famous shallow-lagoon bar-and-beach scene; golf-cart destination, calm swim water.","bookable_category":"day trip / F&B","tier":"comfort","source":"https://agentsgather.com/vacation-rentals-ambergris-caye-belize/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","blurb":"Famous shallow-lagoon bar-and-beach scene; golf-cart destination, calm swim water.","when":"late-Dec through April","commission":"tour + F&B affiliate","accessed":"2026-07-06","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","romance":"destination","tropical":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Tropical Islands / Beaches","si_map_basis":"normalised from free text ''Tropical Islands / Beaches'' by gen_normalise_jewel_si"},{"name":"San Pedro town + Belikin nightlife","status":"live","hook":"Sand-street town core, dockside bars, live music, Lobster Festival hub.","bookable_category":"F&B / event","tier":"essential","source":"https://www.thephoenixbelize.com/explore-more/ultimate-guide-belize-lobster-season-san-pedro + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","blurb":"Sand-street town core, dockside bars, live music, Lobster Festival hub.","when":"late-Dec through April","commission":"F&B / event affiliate","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","romance":"destination","tropical":"primary"},"commission_lane":["affiliate","event"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Tropical Islands / Beaches","si_map_basis":"normalised from free text ''Tropical Islands / Beaches'' by gen_normalise_jewel_si"},{"name":"Sunset sail / private charter","status":"live","hook":"Champagne catamaran sail over the reef lagoon; the honeymoon signature.","bookable_category":"charter / activity","tier":"premier","source":"https://www.viaventure.com/destinations/belize/ambergris-caye/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Champagne catamaran sail over the reef lagoon; the honeymoon signature.","when":"late-Dec through April","commission":"Fora / activity affiliate","accessed":"2026-07-06","wells":["move"],"wells_basis":"derived from name/blurb/hook","si_all":["romance","tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","romance":"primary","tropical":"evidenced"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What is the best diving and snorkeling on Ambergris Caye?","a":"Start at Hol Chan Marine Reserve and Shark Ray Alley. The signature ~30-ft channel dive delivers moray, turtles and 160+ fish species, while Shark Ray Alley — added as Zone D in 1999 — puts you in shallow water with docile 4–6 ft nurse sharks and southern stingrays. Both are guided, beginner-friendly profiles because they are shallow and protected.","source":"en.wikipedia.org, 2026-07-06","si_tag":"liveaboard","accessed":"2026-07-06"},{"q":"Do you need a car on Ambergris Caye?","a":"No — the island runs on golf carts, not cars, and beachfront San Pedro properties sit a 10-minute walk from the airstrip and steps from the water-taxi dock. English is the official language (Belize is the only English-official nation in Central America), so North American travelers move through town with zero language friction.","source":"agentsgather.com, 2026-07-06","si_tag":"tropical","accessed":"2026-07-06"},{"q":"Where should you stay for a honeymoon on Ambergris Caye?","a":"For seclusion, Cayo Espanto is a private island 3 miles off San Pedro with 7 all-inclusive villas and an 18-guest cap from ~US$1,695/villa/night; for adults-only boutique romance, Matachica offers thatched casitas. Both read romance-forward because the property caps guest count and builds the stay around couples.","source":"aprivateisland.com, 2026-07-06","si_tag":"romance","accessed":"2026-07-06"},{"q":"Can you fish the Grand Slam from Ambergris Caye?","a":"Yes — Ambergris fronts 400+ sq mi of flats, channels and lagoons where bonefish, permit and tarpon can all be landed in one day, with El Pescador the Orvis-endorsed base for 50+ years. Tarpon peaks July–September; bonefish and permit run year-round, so the slam is a realistic single-day target.","source":"elpescador.com, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"What''s the real risk to plan for on Ambergris Caye?","a":"Island remoteness for serious medical events, not crime. San Pedro''s Lighthouse Medical Center handles urgent care, but serious trauma routes to Karl Heusner Memorial Hospital in Belize City — the only trauma centre in Belize — then to the US, requiring air/water transfer off the island. Dengue is the primary mosquito-borne concern; there is no malaria on the cayes (Belize was WHO-certified malaria-free in 2023).","source":"belizetravelinsider.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"},{"q":"Is diving the Great Blue Hole dangerous?","a":"It is an advanced dive, not a beginner novelty. The Blue Hole bottoms below recreational limits (~410 ft total); recreational dives target ~130 ft along the stalactite ledges, so treat it as advanced/technical-adjacent with sound gas planning. The offshore boat crossing is 2.5–3 hours each way, or ~20 minutes by scenic flight from San Pedro.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"}],"seo":{"meta_title":"Ambergris Caye & San Pedro, Belize: Dive the Reef, Stay Well | TravelWell.World","meta_description":"Belize''s #1 island — dive Hol Chan and Shark Ray Alley, honeymoon at Cayo Espanto or Matachica, chase the Grand Slam on the flats. National hyperbaric chamber on-island. TravelWell.","slug":"ambergris-caye-belize","primary_keyword":"Ambergris Caye Belize","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"en","local_keywords":["Ambergris Caye Belize","San Pedro Belize diving","Hol Chan Marine Reserve snorkel","Ambergris Caye honeymoon resort","Cayo Espanto private island Belize","Belize barrier reef diving","Ambergris Caye villa rental","Shark Ray Alley tour","Belize Grand Slam fly fishing","Great Blue Hole day trip San Pedro"],"hreflang":["en"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/belize","read":"2026-08-20T14:53:57Z","source_updated":"2026-06-12T10:40:30+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"Dive Liveaboards / Reef Diving","status":"live"},{"si":"romance","status":"live"},{"si":"expedition","status":"live"}],"ultra":[{"name":"Cayo Espanto","why_ultra":"Private-island, 7 all-inclusive seafront villas incl. overwater Casa Ventanas, 18-guest cap, 24-hr dedicated houseman, chef-tailored meals, whole-island buyout.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"resort credit / arrival amenity / upgrade on availability where consortia-eligible (confirm preferred status)","mor":"commissionable AOR (not merchant)","tier":"ultra"},{"name":"Victoria House Resort & Spa","why_ultra":"Five-star colonial-Caribbean flagship, spa, personalized service; ranks with the island''s top hotels.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"},{"name":"Matachica Resort & Spa","why_ultra":"Adults-only boutique, private thatched casitas, romance-forward.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"},{"name":"Las Terrazas","why_ultra":"Design-led north-shore residences, full kitchens, sea-view balconies.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"}],"source_verified":"2026-07-06","hero":{"query":"Ambergris Caye / San Pedro, Belize"},"geo":{"lat":17.9214,"lng":-87.9611},"orbit":[{"id":"blue-hole-belize","jewels":8,"si":["liveaboard","expedition","tropical"]},{"id":"caye-caulker-belize","jewels":9,"si":["tropical","liveaboard","expedition","ocean","culinary"]},{"id":"hopkins-belize","jewels":8,"si":["tropical","expedition","culture"]},{"id":"placencia-belize","jewels":8,"si":["liveaboard","expedition","diveglobal","ocean","wildlife","culture"]},{"id":"san-ignacio-belize","jewels":13,"si":["expedition","culture","romance"]}],"orbit_country":[]}'::jsonb, 4),
  ('antigua-guatemala', '10S', 'Antigua', 'Guatemala', 'Colonial streets under two volcanoes', 'live', 'verified', 'kyoto', 'Guatemala', '{"expedition","culture","culinary","wildlife"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["UNESCO World Heritage colonial city (16th-18th c. Spanish architecture) cradled beneath Volcanoes Agua, Fuego and Acatenango.","Base for the Acatenango overnight trek (summit 3,976 m) with front-row views of continuously erupting Fuego; Pacaya (2,552 m) is the gentler guided lava hike.","Semana Santa is the most famous Holy Week in the Americas - dawn processions over colored-sawdust alfombras; books ~1 year ahead on tiny inventory.","Premier coffee origin: Finca Filadelfia (est. 1870) and nonprofit De la Gente run finca-to-cup tours minutes from the plaza.","A rising colonial-wedding and honeymoon destination anchored by converted-palace boutique hotels (Casa Santo Domingo, Palacio de Dona Leonor, Pensativo House)."],"safety":{"emergency":"110 police (PNC) / 122-123 bomberos (fire-rescue) / 128 Cruz Roja ambulance / 1500 PROATUR tourist assistance; Antigua POLITUR tourist police","hospital":"Hospital Nacional Pedro de Bethancourt (Antigua) + private clinics for stabilization; major trauma/evac to Guatemala City ~1 hr","l3_disclosure":true,"stay_in_zone":true,"air_access_verified":true,"altitude":"Antigua ~1,500 m (mild); Acatenango summit 3,976 m = serious AMS; Pacaya ~2,552 m","water":"bottled/purified only","malaria":"no malaria risk in Antigua (highland); dengue/Zika precaution advised","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/guatemala","read":"2026-09-01T16:18:35Z","page_updated":"2026-08-13T14:45:16+01:00","source_country":"guatemala","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"Within 5km of the Mexican border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"The towns of Santa Ana Huista, San Antonio Huista and La Democracia, in Huehuetenango","lvl":3,"posture":"all-but-essential"}]},"timing":{"inflection_curve_start":"peak dry season Nov-Mar (baseline); Feb is the sweet spot (crowds dip, dry)","peak":"Semana Santa (Holy Week) late Mar/early Apr - THE event; 2027 ~Mar 24-28 (Good Friday Mar 26)","fire_date":"general dry-season curve: fire ~mid-October (curve-start -1-2 wks); Semana Santa 2027: fire ~Apr-May 2026 (~1 yr ahead), last-call ''book by January''","shoulder":"late Oct-Nov & Feb (dry, thinner crowds, easier rates)","green":"May-Oct wet season (lower rates; Sep-Oct wettest but quietest/cheapest)","booking_lead":"Semana Santa ~1 year; weddings 9-12 months; general dry-season 2-3 months","off_season_specials":"wet-months ''quiet Antigua'' value: coffee-finca/roasting tours, jade & textile workshops, cooking classes, Casa Santo Domingo museums + spa, guided treks with flexible dates","event_peaks":["Semana Santa (late Mar/early Apr)","Sumpango Barriletes Gigantes giant-kite festival (Nov 1, All Saints)","Christmas/New Year"]},"jewels":[{"name":"Acatenango sunrise-over-Fuego overnight","status":"live","hook":"Guided overnight ridge camp at ~3,500 m watching Fuego erupt through the night and sunrise over the highlands.","bookable_category":"guided overnight trek (guided-only)","tier":"premier","source":"https://www.muchbetteradventures.com/magazine/acatenango-volcano-hike-guide/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Guided overnight ridge camp at ~3,500 m watching Fuego erupt through the night and sunrise over the highlands.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / Viator-GetYourGuide 4-8%; park + guide fees pass-through","wells":["stay","activities"],"wells_basis":"derived from nam