,"expedition":"destination","wildlife":"destination"},"commission_lane":["DMC","hotel","event"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cerro de la Cruz viewpoint","status":"future","hook":"Hilltop cross with the classic Antigua panorama framed by Volcan Agua.","bookable_category":"free / guided city tour","tier":"essential","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Hilltop cross with the classic Antigua panorama framed by Volcan Agua.","when":"year-round","commission":"bundled into commissionable city tour","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination","wildlife":"destination"},"commission_lane":["bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Santo Domingo del Cerro sculpture park","status":"future","hook":"Hilltop art-and-garden annex above Casa Santo Domingo with city + volcano views; free hotel shuttle.","bookable_category":"free / hotel shuttle add-on","tier":"essential","source":"https://www.casasantodomingo.com.gt/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Hilltop art-and-garden annex above Casa Santo Domingo with city + volcano views; free hotel shuttle.","when":"Semana Santa  late Mar/early Apr","commission":"pairs with Casa Santo Domingo stay (hotel AOR)","wells":["stay","move"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination","wildlife":"destination"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Jade museum + workshop","status":"future","hook":"Working jade ateliers demonstrating Guatemala''s Maya jade tradition; high-margin retail tie-in.","bookable_category":"guided artisan tour","tier":"premier","source":"https://www.dlgcoffee.org/coffee-tour","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Working jade ateliers demonstrating Guatemala''s Maya jade tradition; high-margin retail tie-in.","when":"year-round","commission":"artisan-tour affiliate; retail non-commissionable","wells":["activities","shop"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination","wildlife":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Chichicastenango market day-trip","status":"future","hook":"Thursday/Sunday highland Maya market of textiles and masks.","bookable_category":"DMC day tour (cleared corridor)","tier":"comfort","source":"https://www.martsam.com/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Thursday/Sunday highland Maya market of textiles and masks.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / affiliate 4-8%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary","culture"],"shelf_fit":{"culinary":"evidenced","culture":"primary","expedition":"destination","wildlife":"destination"},"commission_pct_low":10,"commission_pct_high":12,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Ciudad Vieja (first colonial capital)","status":"future","hook":"Guatemala''s original 1527 capital, destroyed by a 1541 lahar, just outside Antigua - deep-history layer.","bookable_category":"guided cultural add-on","tier":"essential","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Guatemala''s original 1527 capital, destroyed by a 1541 lahar, just outside Antigua - deep-history layer.","when":"Semana Santa  late Mar/early Apr","commission":"bundled into commissionable heritage tour","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination","wildlife":"destination"},"commission_lane":["bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Finca Filadelfia coffee tour","status":"future","hook":"Finca-to-cup tour on an 1870-founded estate, one of Guatemala''s first coffee farms; ~$20, on-site hotel + restaurant.","bookable_category":"coffee-finca tour (direct/Viator)","tier":"comfort","source":"https://www.visit-antigua.com/finca-filadelfia.php","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Finca-to-cup tour on an 1870-founded estate, one of Guatemala''s first coffee farms; ~$20, on-site hotel + restaurant.","when":"Semana Santa  late Mar/early Apr","commission":"Viator affiliate 4-8%; direct pass-through","wells":["stay","eat","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","expedition":"destination","wildlife":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"De la Gente community coffee tour","status":"future","hook":"Nonprofit farmer-led tour in San Miguel Escobar (~4 hr, ~$38 incl. shuttle + beans) - responsible-tourism moat.","bookable_category":"community coffee tour","tier":"essential","source":"https://www.dlgcoffee.org/coffee-tour","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Nonprofit farmer-led tour in San Miguel Escobar (~4 hr, ~$38 incl. shuttle + beans) - responsible-tourism moat.","when":"Semana Santa  late Mar/early Apr","commission":"affiliate/donation model; largely pass-through - brand-values proof point","wells":["move","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","expedition":"destination","wildlife":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Guatemalan cooking class","status":"future","hook":"Hands-on colonial-kitchen class (pepian, tamales, tortillas); rainy-day-proof culinary depth.","bookable_category":"Viator/GetYourGuide class","tier":"comfort","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Hands-on colonial-kitchen class (pepian, tamales, tortillas); rainy-day-proof culinary depth.","when":"Semana Santa  late Mar/early Apr","commission":"affiliate 4-8%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary","culture"],"shelf_fit":{"culinary":"primary","culture":"evidenced","expedition":"destination","wildlife":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Sumpango Barriletes Gigantes giant-kite festival","status":"future","hook":"40-ft+ handmade kites flown in the cemetery on All Saints'' Day (Nov 1) to commune with the dead.","bookable_category":"DMC day tour (Nov 1 only)","tier":"comfort","source":"https://tropicanahostel.com/antigua-weather-what-to-expect-and-the-best-time-to-visit/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","blurb":"40-ft+ handmade kites flown in the cemetery on All Saints'' Day (Nov 1) to commune with the dead.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / affiliate 4-8%; entry pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"destination","wildlife":"primary"},"commission_pct_low":10,"commission_pct_high":12,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"}],"faq":[{"q":"How hard is the Acatenango overnight volcano trek?","a":"It''s a serious guided overnight — roughly 1,570 m of ascent to a 3,976 m summit over a 10–12-hour trek split across two days, with base camp near 3,500 m. It''s worth it because you watch Fuego erupt through the night, but altitude and cold are real, so TWW sells reputable guided operators only.","source":"theworldtravelguy.com, Accessed 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"Is Antigua a good place for a wedding or honeymoon?","a":"Yes — Antigua is a genuinely rising colonial-wedding city, because its converted-palace boutique hotels deliver character at the luxury-boutique level: Casa Santo Domingo (5-star, #11 of 102, 4.6★, 2,724 reviews), palace-suite Palacio de Doña Leonor, and adults-only 26-room Pensativo House. Colonial weddings book 9–12 months ahead.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"romance","accessed":"2026-07-06"},{"q":"When is Semana Santa 2027 and how far ahead should I book?","a":"Book about a year ahead. Semana Santa 2027 runs ~March 24–28 (Good Friday Mar 26), the most famous Holy Week in the Americas, and Antigua has limited hotel inventory — \"the best places sell out months in advance.\" Fire the booking a full year out, with a \"book by January\" last-call.","source":"livinginguatemala.com, Accessed 2026-07-06","si_tag":"culture","accessed":"2026-07-06"},{"q":"Can I tour a coffee farm from Antigua?","a":"Yes, minutes from the plaza. Finca Filadelfia — founded 1870 as one of Guatemala''s first coffee farms — runs ~2-hour finca-to-cup tours (~$20), and nonprofit De la Gente runs a ~4-hour farmer-led tour in San Miguel Escobar (~$38 incl. shuttle + beans), because Antigua is a premier coffee origin.","source":"visit-antigua.com, Accessed 2026-07-06","si_tag":"culinary","accessed":"2026-07-06"},{"q":"Does Antigua have spa and wellness options?","a":"Yes — the anchor is the 5-star Hotel Museo Spa Casa Santo Domingo, whose spa sits alongside six on-site museums inside 16th-century Dominican monastery ruins, making it Antigua''s iconic wellness-and-culture address. It''s a quiet colonial-retreat market rather than a resort-spa one.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"wellness","accessed":"2026-07-06"},{"q":"Can I see the giant-kite festival from Antigua?","a":"Yes, as a Nov 1 day-trip. The Sumpango Barriletes Gigantes festival flies 40-ft+ handmade kites in the cemetery on All Saints'' Day to commune with the dead — visually stunning and uniquely Guatemalan, an easy DMC day tour from Antigua.","source":"tropicanahostel.com, Accessed 2026-07-06","si_tag":"wildlife","accessed":"2026-07-06"},{"q":"What''s the real risk to plan for on Acatenango?","a":"Cold, not lava. Base-camp temperatures drop to 0 °C to −5 °C; on January 8, 2017, six Guatemalan hikers died of hypothermia on Acatenango after arriving unprepared — an exposure/preparation failure, not a lava event. Book only reputable guided operators who supply proper down layers, tents and a real sleeping system.","source":"theworldtravelguy.com, Accessed 2026-07-06","si_tag":"safety","accessed":"2026-07-06"}],"seo":{"meta_title":"Antigua Guatemala Travel Guide 2026 — Volcanoes, Semana Santa & Colonial Weddings | TravelWell.World","meta_description":"Plan Antigua Guatemala: the Acatenango/Fuego overnight volcano trek (guided-only, 3,976 m), world-famous Semana Santa alfombras, coffee fincas, colonial-wedding hotels, and clear safety guidance.","slug":"antigua-guatemala","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":["en","es-GT"],"local_keywords":["qué hacer en Antigua Guatemala","Acatenango tour","Semana Santa Antigua","bodas Antigua Guatemala","tour de café Antigua","volcán Pacaya Antigua","hoteles de lujo Antigua Guatemala","alfombras Semana Santa"],"hreflang":["en","es-GT"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/guatemala","read":"2026-08-20T14:47:53Z","source_updated":"2026-08-13T14:45:16+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"culinary","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Hotel Museo Spa Casa Santo Domingo","why_ultra":"5-star in 16th-c. Dominican monastery ruins; six museums + spa; #11 of 102 Antigua hotels; Antigua''s iconic top-of-market address","earning":"on application / host-Virtuoso or Fora where eligible","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"luxury"},{"name":"Palacio de Dona Leonor","why_ultra":"converted colonial palace, antique-furnished grand suites in the historic core; romance/honeymoon standout","earning":"on application / 