  ('banos-ecuador', '10S', 'Baños de Agua Santa, Ecuador', 'Ecuador', 'Baños de Agua Santa', 'live', 'verified', 'mountainValley', 'Andes (Quito) & Galápagos', '{"expedition","romance","wellness"}', '{}', '{"essential","comfort","luxury"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","air_access_verified":"No airport in Baños — access via UIO (Mariscal Sucre, Quito) + ~3-3.5 hr road transfer (~180 km)","altitude_m":1820,"altitude_notes":{"banos_m":1820,"casa_del_arbol_runtun_m":2600,"mild_ams":"uncommon at town level (1,820m); watch if arriving from Quito 2,850m or higher paramo; exertion at 2,600m viewpoints is real work","trauma":"Local hospital for stabilization; serious trauma routes to Ambato (~40 min) then Quito (~3-3.5 hr); complex cases evac to US (Miami)"},"volcano":{"name":"Tungurahua","type":"active stratovolcano (~5,023m)","status_2026":"background / very-low IG-EPN alert; no eruption activity; 24/7 monitoring; UNESCO Geopark (2025)","history":"near-continuous eruption 1999-2016, quiet since 2016","rule":"Re-verify live IG-EPN status before each booking; know town ashfall/lahar evacuation routes","monitoring_source":"https://www.igepn.edu.ec/tungurahua"},"water":"not reliably potable — bottled/filtered (distinct from thermal-bath waters, for soaking not drinking)","advisory_source":"https://www.gov.uk/foreign-travel-advice/ecuador","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/ecuador","read":"2026-09-01T16:19:48Z","page_updated":"2026-07-10T10:44:44+01:00","source_country":"ecuador","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The Coastal Region provinces of Esmeraldas, Manabí, Santa Elena, Guayas, El Oro, Los Ríos and Santo Domingo de los Tsáchilas","lvl":3,"posture":"all-but-essential","except":["airside transit within Guayaquil Airport"],"note":"Gang-related violence linked to organised crime; the city of Guayaquil is inside this restriction."},{"name":"Within 20km of the Ecuador-Colombia border","lvl":3,"posture":"all-but-essential","except":["the El Ángel Ecological Reserve","the Rumichaca border crossing","the town of Tulcán","the Pan-American Highway (in Carchi province)"]}]},"timing":{"peak":["Sep","Oct","Nov","Dec","Jan","Feb"],"shoulder_green":["Mar","Apr","May","Jun","Jul","Aug"],"inflection":["Aug","Feb","Mar"],"fire_date":"curve-start minus 1-2 weeks (mid-Aug for the Sep-Feb dry peak; 1-2 weeks ahead of Ecuadorian holiday weekends/Carnaval/Semana Santa); fire against the arriving Quito curve when Baños rides as an Andes/Amazon attach","events":["Ecuadorian national holiday weekends (feriados) — domestic-demand spikes","Carnaval (Feb-Mar)","Semana Santa"],"rafting_note":"Pastaza Class III+ year-round; Class IV seasonal (~Aug-May)"},"jewels":[{"name":"Casa del Árbol — Swing at the End of the World","tier":"essential","source":"https://www.viator.com/Banos-attractions/Casa-del-Arbol-Swing/d22150-a19710","timing":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the iconic treehouse swing on the Runtún ridge, launching out over the Tungurahua gorge; entry ~$1, 07:00–19:00, harness-secured, 18+","si":"expedition","blurb":"the iconic treehouse swing on the Runtún ridge, launching out over the Tungurahua gorge; entry ~$1, 07:00–19:00, harness-secured, 18+","when":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","commission":"Guided swing/viewpoint tour affiliate or DMC leg (entry non-commissionable)","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Pailón del Diablo (Devil''s Cauldron waterfall)","ti